"""Carga el catálogo de zapatillas desde sneaks_data.json.

Uso:
    python seed.py           # carga productos solo si la tabla está vacía
    python seed.py --force   # borra pedidos y productos y recarga el catálogo
"""
import json
import os
import sys

from database import init_db, get_connection
from models.user import create_user

# Cuenta usada por el botón "Cuenta de Prueba" del login
DEMO_USER = {"name": "Usuario Demo", "email": "demo@clickandbuy.cl", "password": "demo1234"}

# Path to the JSON file generated by sneaks-fetcher
DATA_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sneaks_data.json")


def load_products(path=DATA_FILE):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def seed_products(products, force=False):
    """Inserta los productos y devuelve (insertados, omitidos)."""
    init_db()
    conn = get_connection()

    existing = conn.execute("SELECT COUNT(*) FROM products").fetchone()[0]
    if existing and not force:
        conn.close()
        return 0, 0

    if force:
        # order_items referencia a products, así que los pedidos se borran primero
        conn.execute("DELETE FROM order_items")
        conn.execute("DELETE FROM orders")
        conn.execute("DELETE FROM products")

    inserted = 0
    skipped = 0
    for p in products:
        # Validate minimum required fields
        if not p.get("name") or not p.get("brand") or not p.get("price"):
            skipped += 1
            continue

        conn.execute(
            """INSERT INTO products (name, brand, category, price, price_usd, description,
               image_url, stock, sizes, style_id, colorway, release_date, resell_links)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                p["name"],
                p["brand"],
                p.get("category", "Lifestyle"),
                p["price"],
                p.get("price_usd", 0),
                p.get("description", ""),
                p.get("image_url", ""),
                p.get("stock", 10),
                json.dumps(p.get("sizes", [])),
                p.get("style_id", ""),
                p.get("colorway", ""),
                p.get("release_date", ""),
                json.dumps(p.get("resell_links", {})),
            ),
        )
        inserted += 1

    conn.commit()
    conn.close()
    return inserted, skipped


def ensure_demo_user():
    """Crea la cuenta demo si no existe. Devuelve True si la creó."""
    init_db()
    return create_user(DEMO_USER["name"], DEMO_USER["email"], DEMO_USER["password"]) is not None


def print_summary():
    conn = get_connection()
    brands = conn.execute("SELECT brand, COUNT(*) as c FROM products GROUP BY brand ORDER BY c DESC").fetchall()
    categories = conn.execute("SELECT category, COUNT(*) as c FROM products GROUP BY category ORDER BY c DESC").fetchall()
    conn.close()

    print("\n[RESUMEN]")
    print("   Marcas:")
    for b in brands:
        print(f"     • {b['brand']}: {b['c']} productos")
    print("   Categorías:")
    for c in categories:
        print(f"     • {c['category']}: {c['c']} productos")


def main(argv):
    # Fix Windows console encoding
    if sys.platform == "win32":
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")

    if not os.path.exists(DATA_FILE):
        print(f"[ERROR] No se encontro {DATA_FILE}")
        print("   Ejecuta primero: cd ../sneaks-fetcher && node fetch.js")
        return 1

    force = "--force" in argv
    products = load_products()
    print(f"[INFO] {len(products)} productos en sneaks_data.json")

    inserted, skipped = seed_products(products, force=force)
    if ensure_demo_user():
        print(f"[OK] Cuenta demo creada: {DEMO_USER['email']} / {DEMO_USER['password']}")

    if inserted == 0 and skipped == 0:
        print("[INFO] La base ya tiene productos. Usa --force para recargar (borra los pedidos).")
        return 0

    print(f"[OK] {inserted} productos insertados exitosamente.")
    if skipped > 0:
        print(f"[WARN] {skipped} productos omitidos (datos incompletos).")
    print_summary()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
